											else
												ctxMenu = XTemplateSpawn("PDASquadManagementFilterMenu", dlg, dlg)
												ctxMenu:SetAnchor(button.box)
												--ctxMenu:SetMaxWidth(button.MaxWidth)
												ctxMenu:SetMinWidth(button.MinWidth)
